import{_ as p,a0 as i,w as l,s as h,I as o,x as t,a1 as e,A as s,ao as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"Thonny：在学校教授 Python 编程的理想 IDE | LCTT x X-CMD","titleTemplate":false,"description":"Thonny：在学校教授 Python 编程的理想 IDE | LCTT (202206) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Thonny：在学校教授 Python 编程的理想 IDE | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Thonny：在学校教授 Python 编程的理想 IDE | LCTT (202206) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202206/20220613 Thonny is an Ideal IDE for Teaching Python Programming in Schools","title":"Thonny：在学校教授 Python 编程的理想 IDE","tag":"202206","desc":""},"relativePath":"202206/20220613 Thonny is an Ideal IDE for Teaching Python Programming in Schools.md","filePath":"[post].md"}'),d={name:"202206/20220613 Thonny is an Ideal IDE for Teaching Python Programming in Schools.md"};function y(m,n,u,f,P,g){const a=i("Link");return l(),h("div",null,[n[20]||(n[20]=o("h1",{id:"thonny-在学校教授-python-编程的理想-ide",tabindex:"-1"},[t("Thonny：在学校教授 Python 编程的理想 IDE "),o("a",{class:"header-anchor",href:"#thonny-在学校教授-python-编程的理想-ide","aria-label":"Permalink to “Thonny：在学校教授 Python 编程的理想 IDE”"},"​")],-1)),n[21]||(n[21]=o("p",null,"在 Linux 中运行一个 Python 程序只需要简单地在终端中执行 Python 文件就行。",-1)),n[22]||(n[22]=o("p",null,"但这对人们来说不是很方便，也不能帮助你调试你的程序。太原始了。",-1)),o("p",null,[n[1]||(n[1]=t("有几个 IDE 和文本编辑器可以用于 Python 开发。Linux 用户可以使用 ",-1)),e(a,{href:"https://itsfoss.com/install-pycharm-ubuntu/"},{default:s(()=>[...n[0]||(n[0]=[t("PyCharm 社区版",-1)])]),_:1}),n[2]||(n[2]=t("。",-1))]),n[23]||(n[23]=o("p",null,"我最近发现了另一个专门为 Python 初学者制作的 IDE。我喜欢这个应用的想法，因此我在这里与你分享。",-1)),n[24]||(n[24]=o("h3",{id:"thonny-是一个跨平台、开源的-python-ide-适合初学者使用",tabindex:"-1"},[t("Thonny 是一个跨平台、开源的 Python IDE，适合初学者使用 "),o("a",{class:"header-anchor",href:"#thonny-是一个跨平台、开源的-python-ide-适合初学者使用","aria-label":"Permalink to “Thonny 是一个跨平台、开源的 Python IDE，适合初学者使用”"},"​")],-1)),o("p",null,[e(a,{href:"https://thonny.org/"},{default:s(()=>[...n[3]||(n[3]=[t("Thonny",-1)])]),_:1}),n[4]||(n[4]=t(" 在用户界面和用户体验方面，感觉就像 Python 版本的 Eclipse。考虑到大多数 C++ 和 Java 的初学者都是从 Eclipse 开始的，而且许多人后来一直使用它，这也不完全是一件坏事。",-1))]),n[25]||(n[25]=r('<p>它不是一个新的工具。它已经出现好几年了。我没有用 Python 进行编码，所以直到最近才发现它。</p><p>Thonny 专注于 Python，提供了帮助 Python 初学者了解其程序行为的功能。让我们来看看这些功能。</p><h4 id="即装即用" tabindex="-1">即装即用 <a class="header-anchor" href="#即装即用" aria-label="Permalink to “即装即用”">​</a></h4><p>Thonny 自带 Python，所以你不需要为安装 Python 做额外的努力。这对 Linux 用户来说不是什么大事，因为大多数发行版都默认安装了 Python。</p><p>界面很简单。它给你一个编辑器，你可以写你的 Python 程序，然后点击运行按钮或使用 <code>F5</code> 键来运行程序。输出显示在底部。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/06/thonny-hello-world.png" alt="thonny hello world"></p><h4 id="查看变量" tabindex="-1">查看变量 <a class="header-anchor" href="#查看变量" aria-label="Permalink to “查看变量”">​</a></h4><p>在 “<ruby>查看<rt>View</rt></ruby>-&gt;<ruby>变量<rt>Variables</rt></ruby>”，你可以看到所有变量的值。不需要将它们全部打印出来。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/06/thonny-variable-pane.png" alt="thonny variable pane"></p><h4 id="内置调试器" tabindex="-1">内置调试器 <a class="header-anchor" href="#内置调试器" aria-label="Permalink to “内置调试器”">​</a></h4><p>通过使用调试器一步步运行你的程序。你可以从顶部的菜单或使用 <code>Ctrl + F5</code> 键访问它。在这里你甚至不需要设置断点。你可以用 <code>F6</code> 进入大步骤，或用 <code>F7</code> 进入小步骤。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/06/thonny-step-by-step-f6.png" alt="thonny step by step f6"></p><p>在小步骤中，你可以看到 Python 是如何看待你的表达式的。这对新的程序员理解他们的程序为什么以某种方式表现非常有帮助。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/06/thonny-step-by-step-f7.png" alt="thonny step by step f7"></p><p>不止这样。对于函数调用，它会打开一个新的窗口，里面有独立的局部变量表和代码指针。超级酷!</p><h4 id="语法错误高亮" tabindex="-1">语法错误高亮 <a class="header-anchor" href="#语法错误高亮" aria-label="Permalink to “语法错误高亮”">​</a></h4><p>初学者经常会犯一些简单的语法错误，如缺少小括号、引号等。Thonny 会在编辑器中立即指出来。</p><p>本地变量也可以从视觉上与全局变量区分开来。</p><h4 id="自动补全" tabindex="-1">自动补全 <a class="header-anchor" href="#自动补全" aria-label="Permalink to “自动补全”">​</a></h4><p>你不需要输入所有的东西。Thonny 支持自动补全代码，这有助于加快编码。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/06/thonny-auto-complete.png" alt="thonny auto complete"></p><h4 id="访问系统-shell" tabindex="-1">访问系统 shell <a class="header-anchor" href="#访问系统-shell" aria-label="Permalink to “访问系统 shell”">​</a></h4><p>在工具中，你可以访问系统 shell。在这里你可以安装新的 Python 包或学习从命令行处理 Python。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/06/thonny-shell-terminal.png" alt="thonny shell terminal"></p><p>请注意，如果你使用 Flatpak 或 Snap，Thonny 可能无法访问系统 shell。</p><h4 id="从-gui-管理-pip" tabindex="-1">从 GUI 管理 Pip <a class="header-anchor" href="#从-gui-管理-pip" aria-label="Permalink to “从 GUI 管理 Pip”">​</a></h4><p>进入工具和管理包。它会打开一个窗口，你可以从这个 GUI 中安装 Pip 软件包。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/06/thonny-manage-packages.png" alt="thonny manage packages"></p><p>对于学习 Python 来说，功能足够好，对吗？让我们看看如何安装它。</p><h3 id="在-linux-上安装-thonny" tabindex="-1">在 Linux 上安装 Thonny <a class="header-anchor" href="#在-linux-上安装-thonny" aria-label="Permalink to “在 Linux 上安装 Thonny”">​</a></h3><p>Thonny 是一个跨平台的应用。它可用于 Windows、macOS 和 Linux。</p><p>它是一个流行的应用，你可以在大多数 Linux 发行版的仓库中找到它。只要在你的系统的软件中心寻找它。</p><p>另外，你也可以随时使用你的 Linux 发行版的包管理器。</p><p>在 Debian 和基于 Ubuntu 的发行版上，你可以使用 <code>apt</code> 命令来安装它。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install thonny</span></span></code></pre></div><p>它会下载一堆依赖关系和大约 300MB 的软件包。</p><p>安装后，你可以在菜单中搜索它，并从那里安装它。</p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>Thonny 对于初级 Python 程序员来说是个不错的工具。不是说专家不能使用它，但它更适合在学校和学院使用。学生们会发现它有助于学习 Python 和理解他们的代码是如何以某种方式表现出来的。事实上，它最初是在爱沙尼亚的塔尔图大学开发的。</p><p>总的来说，对于 Python 学习者来说是一个很好的软件。</p><hr>',41)),o("p",null,[n[6]||(n[6]=t("via: ",-1)),e(a,{href:"https://itsfoss.com/thonny-python-ide/"},{default:s(()=>[...n[5]||(n[5]=[t("https://itsfoss.com/thonny-python-ide/",-1)])]),_:1})]),o("p",null,[n[11]||(n[11]=t("作者：",-1)),e(a,{href:"https://itsfoss.com/author/abhishek/"},{default:s(()=>[...n[7]||(n[7]=[t("Abhishek Prakash",-1)])]),_:1}),n[12]||(n[12]=t(" 选题：",-1)),e(a,{href:"https://github.com/lkxed"},{default:s(()=>[...n[8]||(n[8]=[t("lkxed",-1)])]),_:1}),n[13]||(n[13]=t(" 译者：",-1)),e(a,{href:"https://github.com/geekpi"},{default:s(()=>[...n[9]||(n[9]=[t("geekpi",-1)])]),_:1}),n[14]||(n[14]=t(" 校对：",-1)),e(a,{href:"https://github.com/wxy"},{default:s(()=>[...n[10]||(n[10]=[t("wxy",-1)])]),_:1})]),o("p",null,[n[17]||(n[17]=t("本文由 ",-1)),e(a,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...n[15]||(n[15]=[t("LCTT",-1)])]),_:1}),n[18]||(n[18]=t(" 原创编译，",-1)),e(a,{href:"https://linux.cn/"},{default:s(()=>[...n[16]||(n[16]=[t("Linux中国",-1)])]),_:1}),n[19]||(n[19]=t(" 荣誉推出",-1))])])}const k=p(d,[["render",y]]);export{x as __pageData,k as default};
